import"./chunk-2NFLSA4Y.js";var a={phaseChanges:{theory:{concept:"[[A phase change is the change of a substance from one state of matter \u2014 solid, liquid or gas \u2014 to another: melting, freezing, boiling (vaporisation) and condensation.]] Heat a block of ice and it first warms up, then melts, the water warms up, then boils, and the steam warms up. While it melts or boils its temperature does not change at all: all the heat goes into changing the state."},section:{states:{title:"Solid, liquid, gas",text:"In a solid the particles are held in fixed places and only vibrate. In a liquid they stay close together but slide past one another, so a liquid flows and takes the shape of its container. In a gas they are far apart and fly freely, filling any space. The hotter the substance, the faster its particles move."},plateau:{title:"Why the temperature stops rising",text:"Temperature measures how fast the particles move. While ice melts, the heat is used to break the bonds that hold the particles in their places, not to speed them up \u2014 so the thermometer stays at 0 \xB0C until the last bit of ice has melted. The same happens at 100 \xB0C while water boils. These flat parts of the heating curve are called plateaus."},latent:{title:"Latent heat",text:"[[The heat needed to change the state of 1 kg is the latent heat: L_f for melting, L_v for boiling.]] Melting 1 kg of ice takes 334 kJ; boiling 1 kg of water takes 2 257 kJ \u2014 almost seven times more, because in a gas the particles must be pulled completely apart. That is why a kettle takes much longer to boil water dry than to bring it to the boil."},reverse:{title:"Freezing and condensing give heat back",text:"The changes also run backwards. When water freezes or steam condenses, the same latent heat is released. Steam at 100 \xB0C burns much worse than water at 100 \xB0C, because it gives up its 2 257 kJ/kg as it condenses on the skin. Farmers spray fruit trees with water on frosty nights: as it freezes it releases heat and protects the blossoms."},pressure:{title:"Boiling depends on pressure",text:"[[A liquid boils when its vapour pushes as hard as the air above it.]] Lower the pressure and it boils at a lower temperature: on top of Mount Everest water boils at about 71 \xB0C, so pasta cooks slowly. A pressure cooker raises the pressure to about 2 atmospheres; the water boils at about 120 \xB0C and food cooks much faster. The melting point hardly depends on pressure."},ice:{title:"Ice floats",text:"Most substances are denser as a solid than as a liquid, so their solid sinks \u2014 solid lead sinks in molten lead. Water is unusual: ice is about 9 % less dense than water and floats. Lakes therefore freeze from the top down, and the ice layer protects the water and the fish beneath it."},check:{title:"Check your understanding",text:"What is the temperature of a glass of water with ice cubes in it? (0 \xB0C, until the ice melts.) Why does boiling water dry take longer than heating it from 0 to 100 \xB0C? Why do mountaineers use pressure cookers? Try each answer in the simulation."}},formula:{warming:"Heat to warm a body by \u0394T (c: specific heat of that state)",melting:"Heat to melt the whole mass at the melting point",boiling:"Heat to boil the whole mass at the boiling point",power:"Heat from a heater of power P in time t",clapeyron:"Boiling point at pressure p (Clausius\u2013Clapeyron, T in kelvin)"},variable:{heat:"Heat added (negative when cooling)",specificHeat:"Specific heat, J/(kg\xB7K): water 4 186, ice 2 100",latentHeat:"Latent heat, J/kg: melting ice 334 000, boiling water 2 257 000"},assumption:{noLoss:"No heat escapes to the room: all of the heater's power goes into the substance.",uniform:"The whole substance always has one temperature (it is stirred well).",constants:"Specific and latent heats are constant typical values.",particles:"The particle window is an illustration: real particles are far smaller and far more numerous."},param:{substance:"Substance",start:"Start as",power:"Heater power",mass:"Mass",pressure:"Pressure",timeScale:"Time speed-up \xD7"},hint:{start:"Starts a little below the melting point (solid), at room temperature (liquid) or above the boiling point (gas).",power:"Positive: heating. Negative: cooling (a freezer).",pressure:"Lower pressure, lower boiling point. 101.3 kPa is normal air pressure at sea level."},preset:{water:"Water",ethanol:"Ethanol (alcohol)",lead:"Lead",solid:"Solid",liquid:"Liquid",gas:"Gas",kettle:"Kettle",gentle:"Small stove",freezer:"Freezer",strongCooling:"Strong cooling",everest:"Everest",seaLevel:"Sea level",cooker:"Pressure cooker"},measure:{temperature:"Temperature",solid:"Solid",liquid:"Liquid",gas:"Gas",heat:"Heat added",meltingPoint:"Melting point",boilingPoint:"Boiling point",fusionHeat:"Heat to melt all of it",vaporisationHeat:"Heat to boil all of it",meltMinutes:"Time spent melting",boilMinutes:"Time spent boiling"},view:{heating:"Heating \xB7 {power}",cooling:"Cooling \xB7 {power}",particles:"Particles (illustration)",axisTemperature:"Temperature, \xB0C",axisTime:"Time, min",status:"{phase} \xB7 {temperature}",phase:{solid:"Solid",melting:"Melting",liquid:"Liquid",boiling:"Boiling",gas:"Gas",freezing:"Freezing",condensing:"Condensing"},moleculesOption:"Particle window",predictionOption:"Expected curve"},graph:{temperature:"Temperature against time",fractions:"Solid, liquid and gas against time"},challenge:{allSteam:{title:"From ice to steam",description:"Start with ice and heat it until all of it has turned into steam.",hint:"Keep heating: the boiling plateau is the longest part."},freeze:{title:"Make ice",description:"Start with a liquid and cool it until it is completely solid.",hint:"Choose a negative power \u2014 a freezer."},ethanol:{title:"Alcohol boils first",description:"Boil ethanol. At what temperature does it boil?",hint:"Choose ethanol and heat it. Compare its boiling point with water."},quickBoil:{title:"Boil it away fast",description:"Boil away at least 0.5 kg of water, starting at room temperature, within 15 minutes.",hint:"Q = m\xB7c\xB7\u0394T + m\xB7L_v. You need enough power \u2014 and less mass helps."},everest:{title:"On top of Everest",description:"Boil water where it boils below 75 \xB0C.",hint:"Lower the pressure \u2014 try the Everest preset."},cooker:{title:"Pressure cooker",description:"Boil water at 115 \xB0C or more.",hint:"Raise the pressure above about 170 kPa."}}}},i={sim:a};export{i as default,a as sim};
